import React from 'react';
const ThongTinCaNhan = () => (
    <div style={{backgroundColor: '#fff', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 12px rgba(0,0,0,0.05)'}}>
        <h2 style={{color: '#2e7d32', marginBottom: '20px'}}>👤 Thông tin cư dân</h2>
        <div style={{display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px'}}>
            <div><label style={{color: '#888'}}>Họ và tên</label><p style={{fontSize: '18px', fontWeight: 'bold'}}>Phan Vinh</p></div>
            <div><label style={{color: '#888'}}>Số điện thoại</label><p style={{fontSize: '18px', fontWeight: 'bold'}}>0905123456</p></div>
            <div><label style={{color: '#888'}}>Căn hộ</label><p style={{fontSize: '18px', fontWeight: 'bold'}}>A101</p></div>
            <div><label style={{color: '#888'}}>Ngày sinh</label><p style={{fontSize: '18px', fontWeight: 'bold'}}>01/01/1995</p></div>
        </div>
        <button style={{marginTop: '20px', padding: '10px 20px', backgroundColor: '#4caf50', color: '#fff', border: 'none', borderRadius: '8px', cursor: 'pointer'}}>Chỉnh sửa thông tin</button>
    </div>
);
export default ThongTinCaNhan;
